CREATE   PROCEDURE [synapse_ce].[usp_Insert_transactioncurrency]
AS
BEGIN
	INSERT INTO [synapse_ce].[transactioncurrency]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[currencyname],
		[currencyprecision],
		[currencysymbol],
		[entityimage_timestamp],
		[entityimage_url],
		[entityimageid],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[isocurrencycode],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[transactioncurrencyid],
		[uniquedscid],
		[versionnumber]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[currencyname],
		stg.[currencyprecision],
		stg.[currencysymbol],
		stg.[entityimage_timestamp],
		stg.[entityimage_url],
		stg.[entityimageid],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[isocurrencycode],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[transactioncurrencyid],
		stg.[uniquedscid],
		stg.[versionnumber]	
	FROM [staging_ce].[transactioncurrency] stg
		LEFT JOIN [synapse_ce].[transactioncurrency] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
